            json.dump({'score': score, 'n': len(seq)}, f)
    except:
        pass

def read_best_file():
    try:
        with open('/home/crv1pi/agent_runs/ac2_plain_s1/run/.best_score') as f:
            return json.loads(f.read())
    except:
        return {'score': 0, 'n': 0}

def neg_score(x):
    x = np.maximum(x, 0)
    try:
        return -evaluate_sequence(x.tolist())
    except:
        return 1e10

def optimize_one(args):
    seed, n, shape_type, maxiter = args
    np.random.seed(seed)
    current_best = read_best_file()['score']

    if shape_type == 0:
        a0 = np.random.uniform(0.02, 0.15)
        ratios = np.random.uniform(1.05, 1.8, n-1)
        x = np.cumprod([a0] + list(ratios))
    elif shape_type == 1:
        p = np.random.uniform(0.3, 2.0)
        x = np.linspace(0.05, 1, n)**p
    elif shape_type == 2:
        a = np.random.uniform(0.3, 2.0)
        x = np.exp(a * np.linspace(0, 1, n)) / np.exp(a)
    elif shape_type == 3:
        x = np.sort(np.random.uniform(0.01, 1, n))
    elif shape_type == 4:
        best14 = [0.13, 0.16, 0.19, 0.22, 0.26, 0.30, 0.35, 0.41, 0.48, 0.57, 0.68, 0.82, 1.0, 1.3]
        x = np.interp(np.linspace(0, 1, n), np.linspace(0, 1, 14), best14/1.3)
        x = x + np.random.randn(n) * 0.03
    elif shape_type == 5:
        x = np.linspace(0.1, 1, n)
        x = x**(np.random.uniform(0.5, 1.5))
    else:
        base = [0.1276, 0.152, 0.1535, 0.1643, 0.1555, 0.1583, 0.1612, 0.1914, 0.1531, 0.1677, 0.1862, 0.187, 0.177, 0.1932, 0.2032, 0.2036, 0.2169, 0.2162, 0.2362, 0.2312, 0.2509, 0.26, 0.2766, 0.2925, 0.3139, 0.3406, 0.3671, 0.4234, 0.4759, 0.6061, 0.9414, 1.0317]
        if n != len(base):
            x = np.interp(np.linspace(0, 1, n), np.linspace(0, 1, len(base)), base)
        else:
            x = np.array(base) + np.random.randn(n) * 0.02

    x = np.maximum(x, 0)
    if x.max() > 0:
        x = x / x.max()

    try:
        result = minimize(neg_score, x, method='Nelder-Mead',
